1	import { useEffect, useMemo, useState, useRef } from "react";
2	import { supabase } from "@/integrations/supabase/client";
3	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/shared/ui/card";
4	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
