73	
74	// Momma Store Palette
75	const COLORS = {
76	  green: "#57715B",
77	  cream: "#F5F5F0",
78	  wood: "#E6DCCF",
79	  gold: "#C5A065",
80	  text: "#2D362E",
81	  red: "#ef4444",
82	};
83	
84	const CHART_COLORS = ['#C5A065', '#57715B', '#E6DCCF', '#2D362E', '#8B4513'];
85	
86	interface LossItem {
87	  id: number;
88	  motivo_perda: string;
89	  observacoes: string | null;
90	  valor_estimado: number | null;
91	  preco_unitario: number | null;
92	  data_identificacao: string | null;
93	  produto_id?: number | null;
94	  produto_master_id?: number | null;
95	  quantidade?: number | null;
96	  produto_nome_perda?: string | null;
97	  responsavel_id?: number | null;
98	  loja_id?: number | null;
99	  foto_url?: string | null;
100	  stores?: {
101	    id: number;
102	    nome: string;
103	  } | null;
104	  produtos_master?: {
105	    preco_custo: number | null;
106	  } | null;
107	  unidade?: string | null;
108	  lote?: string | null;
109	  validade?: string | null;
110	  verificada?: boolean;
111	}
112	
113	const LossCard = ({
114	  item,
115	  users,
116	  currentUserId,
117	  isAdmin,
118	  onDelete,
119	  onVerify,
120	  onImageClick,
121	  isVerified = false
122	}: {
123	  item: LossItem;
124	  users: any[];
125	  currentUserId: number | null;
126	  isAdmin: boolean;
127	  onDelete: () => void;
128	  onVerify?: () => void;
129	  onImageClick: (url: string) => void;
130	  isVerified?: boolean;
131	}) => (
132	  <div
133	    className={cn(
134	      "group relative bg-[#FDFCF8] dark:bg-[#1A1A1A] rounded-2xl p-5 border shadow-sm hover:shadow-md transition-all duration-300",
135	      isVerified ? "border-green-500/30 bg-green-500/5" : "border-[#E6DCCF] dark:border-[#57715B]/20"
136	    )}
137	  >
138	    <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
139	      {/* Column 1: Date & Time */}
140	      <div className="md:col-span-1">
141	        <h4 className="text-[10px] font-bold text-[#8B4513]/60 uppercase tracking-widest mb-1.5">Data registro</h4>
142	        <div className="flex items-center gap-2 text-[#2D362E] dark:text-[#E6DCCF] font-semibold text-sm">
143	          {format(new Date(item.data_identificacao || ""), "dd/MM/yyyy", { locale: ptBR })}
144	          <span className="opacity-60 font-normal">
145	            {format(new Date(item.data_identificacao || ""), "HH:mm", { locale: ptBR })}
146	          </span>
147	        </div>
148	        <div className="mt-2 inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md bg-[#57715B]/5 text-[10px] text-[#57715B] font-bold uppercase tracking-wider">
149	          <Store className="w-3 h-3" />
150	          {item.stores?.nome}
151	        </div>
152	        {item.responsavel_id && (() => {
153	          const user = users.find((u: any) => u.id === item.responsavel_id);
154	          return user ? (
155	            <div className="mt-1.5 text-[10px] text-muted-foreground font-medium truncate max-w-[150px]" title={user.nome}>
156	              por {user.nome}
157	            </div>
158	          ) : null;
159	        })()}
160	      </div>
161	
162	      {/* Column 2: Product */}
163	      <div className="md:col-span-1">
164	        <h4 className="text-[10px] font-bold text-[#8B4513]/60 uppercase tracking-widest mb-1.5">Produto</h4>
165	        <div className="flex items-center gap-3">
166	          <div
167	            className={`h-10 w-10 shrink-0 rounded-lg bg-white dark:bg-black/20 border border-[#E6DCCF] flex items-center justify-center text-[#57715B] overflow-hidden ${item.foto_url ? 'cursor-zoom-in hover:opacity-80 transition-opacity' : ''}`}
168	            onClick={() => item.foto_url && onImageClick(item.foto_url)}
169	          >
170	            {item.foto_url ? (
171	              <img src={item.foto_url} alt={item.produto_nome_perda || "Produto"} className="w-full h-full object-cover" />
172	            ) : (
173	              <Package className="w-5 h-5" />
174	            )}
175	          </div>
176	          <div className="flex flex-col">
177	            <span className="font-bold text-[#2D362E] dark:text-[#E6DCCF] text-sm leading-tight">
178	              {item.produto_nome_perda}
179	            </span>
180	            {item.lote && <span className="text-[10px] text-muted-foreground">Lote: {item.lote}</span>}
181	          </div>
182	        </div>
183	      </div>
184	
185	      {/* Column 3: Quantity */}
186	      <div className="md:col-span-1">
187	        <h4 className="text-[10px] font-bold text-[#8B4513]/60 uppercase tracking-widest mb-1.5">Quantidade / Custo</h4>
188	        <div className="flex flex-col">
189	          <span className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
190	            {item.quantidade} <span className="text-sm font-normal text-[#57715B]">{item.unidade || 'uni'}</span>
191	          </span>
192	          {(() => {
193	            const costPrice = item.produtos_master?.preco_custo;
194	            const costValue = costPrice && item.quantidade ? Number(item.quantidade) * Number(costPrice) : 0;
195	            return costValue > 0 ? (
196	              <span className="text-sm font-semibold text-[#8B4513]">
197	                {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(costValue)}
198	                <span className="text-[10px] font-normal text-muted-foreground ml-1">(custo)</span>
199	              </span>
200	            ) : (
201	              <span className="text-xs text-muted-foreground italic">Sem custo cadastrado</span>
202	            );
203	          })()}
204	        </div>
205	      </div>
206	
207	      {/* Column 4: Reason & Actions */}
208	      <div className="md:col-span-1 flex flex-col h-full justify-between">
209	        <div>
210	          <h4 className="text-[10px] font-bold text-[#8B4513]/60 uppercase tracking-widest mb-1.5">Motivo</h4>
211	          <div className="space-y-2">
212	            <div className="flex items-center gap-2">
213	              <Badge variant="outline" className="border-[#57715B]/30 text-[#57715B] bg-[#57715B]/5 font-normal">{item.motivo_perda}</Badge>
214	            </div>
215	            {item.observacoes && (
216	              <div className="text-xs text-[#2D362E]/80 dark:text-[#E6DCCF]/80">
217	                <span className="font-bold text-[#57715B]">Obs.:</span> {item.observacoes}
218	              </div>
219	            )}
220	          </div>
221	        </div>
222	
223	        {/* Actions */}
224	        <div className="mt-4 flex items-center justify-end gap-2">
225	          {!isVerified && onVerify && isAdmin && (
226	            <Button data-mia-action="verify"
227	              onClick={onVerify}
228	              size="sm"
229	              className="h-8 bg-[#57715B] hover:bg-[#57715B]/90 text-white shadow-sm"
230	            >
231	              <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" />
232	              Verificar
233	            </Button>
234	          )}
235	
236	          {(item.responsavel_id === currentUserId || isAdmin) && (
237	            <Button data-mia-action="delete"
238	              size="icon"
239	              variant="ghost"
240	              className="h-8 w-8 text-black/20 hover:text-red-500 hover:bg-red-50 rounded-full"
241	              onClick={onDelete}
242	            >
243	              <Trash className="w-4 h-4" />
244	            </Button>
245	          )}
246	        </div>
247	      </div>
248	    </div>
249	  </div>
250	);
251	
252	export default function VerificacaoPerdas() {
253	  useMiaPageContext({
254	    description: 'Verificação de Perdas — lançar perda por produto/lote/loja, conferir histórico, fotografar, justificar.',
255	    natural_language_hints: '"lançar perda" = aba Lançar (form); "histórico" = aba Histórico (lista); "perda hoje" = filtro data; lote/validade são obrigatórios; foto opcional mas recomendada.',
256	    capabilities: ['lancar_perda', 'consultar_historico', 'aprovar', 'foto_perda'],
257	    destructive_actions: ['excluir_perda'],
258	    primary_entity: 'perda',
259	  });
260	  const navigate = useNavigate();
261	  const [isLeaving, setIsLeaving] = useState(false);
262	  const [losses, setLosses] = useState<LossItem[]>([]);
263	  const [loading, setLoading] = useState(true);
264	  const [activeTab, setActiveTab] = useState("lancar");
265	  const { toast } = useToast();
266	  const isMobile = useIsMobile();
267	
268	  // Stores, Products, and Users
269	  const [stores, setStores] = useState<{ id: number; nome: string }[]>([]);
270	  const [loadingStores, setLoadingStores] = useState(false);
271	  const [products, setProducts] = useState<{ id: number; nome: string; preco_custo: number | null }[]>([]);
272	  const [loadingProducts, setLoadingProducts] = useState(false);
273	  const [users, setUsers] = useState<{ id: number; nome: string }[]>([]);
274	  const [currentUserId, setCurrentUserId] = useState<number | null>(null);
275	
276	  // Filters
277	  const [filterStore, setFilterStore] = useState<string>("all");
278	  const [filterProduct, setFilterProduct] = useState<string>("");
279	  const [filterDateStart, setFilterDateStart] = useState<string>("");
280	  const [filterDateEnd, setFilterDateEnd] = useState<string>("");
281	
282	  // Form State
283	  const [selectedStore, setSelectedStore] = useState<string>("");
284	  const [selectedProductQuery, setSelectedProductQuery] = useState("");
285	  const [selectedProductId, setSelectedProductId] = useState<string>("");
286	  const [quantity, setQuantity] = useState("");
287	  const [unit, setUnit] = useState("uni");
288	  const [reason, setReason] = useState("");
289	  const [obs, setObs] = useState("");
290	  const [lote, setLote] = useState("");
291	  const [validade, setValidade] = useState("");
292	  const [photoFile, setPhotoFile] = useState<File | null>(null);
293	  const [photoPreview, setPhotoPreview] = useState<string | null>(null);
294	  const [isSubmitting, setIsSubmitting] = useState(false);
295	  const [selectedImage, setSelectedImage] = useState<string | null>(null);
296	  const fileInputRef = useRef<HTMLInputElement>(null);
297	  const isCapturingPhotoRef = useRef(false);
298	
299	  // Chaves de sessionStorage para sobreviver ao kill da aba quando a câmera nativa
300	  // toma foreground no mobile (iOS Safari principalmente). Sem isso, o state da foto
301	  // se perde ao remount e o usuário vê o form "voltar do início" sem mensagem.
302	  const PHOTO_STORAGE_KEYS = {
303	    dataUrl: 'verificacaoPerdas:capturedImage',
304	    name: 'verificacaoPerdas:capturedImageName',
305	    type: 'verificacaoPerdas:capturedImageType',
306	    capturing: 'verificacaoPerdas:isCapturingPhoto',
307	  } as const;
308	
309	  const clearPhotoStorage = () => {
310	    try {
311	      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.dataUrl);
312	      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.name);
313	      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.type);
314	      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.capturing);
315	    } catch {
316	      // ignore — sessionStorage pode estar bloqueado em modo privado
317	    }
318	  };
319	
320	  const { hasPermission, canViewEstoque, isAdmin, loading: permissionsLoading } = usePermissions();
321	  const hasAccess = hasPermission("view_verificacao_perdas") || canViewEstoque() || isAdmin();
322	
323	  // Photo handling
324	  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
325	    isCapturingPhotoRef.current = false;
326	    sessionStorage.removeItem(PHOTO_STORAGE_KEYS.capturing);
327	    if (e.target.files && e.target.files[0]) {
328	      const file = e.target.files[0];
329	      setPhotoFile(file);
330	      const reader = new FileReader();
331	      reader.onload = (ev) => {
332	        const dataUrl = ev.target?.result as string;
333	        setPhotoPreview(dataUrl);
334	        try {
335	          sessionStorage.setItem(PHOTO_STORAGE_KEYS.dataUrl, dataUrl);
336	          sessionStorage.setItem(PHOTO_STORAGE_KEYS.name, file.name);
337	          sessionStorage.setItem(PHOTO_STORAGE_KEYS.type, file.type);
338	        } catch {
339	          // ignore — sessionStorage cheio ou bloqueado; foto continua em memória
340	        }
341	      };
342	      reader.readAsDataURL(file);
343	    }
344	    // Permite re-selecionar o mesmo arquivo
345	    e.target.value = "";
346	  };
347	
348	  const handlePhotoAreaClick = () => {
349	    if (!fileInputRef.current) return;
350	    sessionStorage.setItem(PHOTO_STORAGE_KEYS.capturing, 'true');
351	    isCapturingPhotoRef.current = true;
352	    fileInputRef.current.click();
353	  };
354	
355	  const clearForm = () => {
356	    setSelectedProductQuery("");
357	    setSelectedProductId("");
358	    setQuantity("");
359	    setUnit("uni");
360	    setReason("");
361	    setObs("");
362	    setLote("");
363	    setValidade("");
364	    setPhotoFile(null);
365	    setPhotoPreview(null);
366	    clearPhotoStorage();
367	    if (fileInputRef.current) fileInputRef.current.value = "";
368	  };
369	
370	  const fetchLosses = async () => {
371	    try {
372	      setLoading(true);
373	      const { data, error } = await supabase
374	        .from("perdas")
375	        .select(`
376	          id,
377	          motivo_perda,
378	          observacoes,
379	          valor_estimado,
380	          preco_unitario,
381	          data_identificacao,
382	          produto_nome_perda,
383	          produto_master_id,
384	          quantidade,
385	          responsavel_id,
386	          loja_id,
387	          foto_url,
388	          unidade,
389	          lote,
390	          validade,
391	          verificada,
392	          stores:lojas(id, nome),
393	          produtos_master(preco_custo)
394	        `)
395	        .order("data_identificacao", { ascending: false });
396	
397	      if (error) throw error;
398	      setLosses((data as any) || []);
399	    } catch (err: any) {
400	      console.error("Erro ao carregar perdas:", err);
401	      toast({
402	        title: "Erro",
403	        description: "Não foi possível carregar o histórico de perdas.",
404	        variant: "destructive",
405	      });
406	    } finally {
407	      setLoading(false);
408	    }
409	  };
410	
411	  // Restaura foto capturada se a aba foi descarregada enquanto a câmera nativa
412	  // estava aberta (comum em iOS Safari/Android com pouca RAM). Ver PHOTO_STORAGE_KEYS.
413	  useEffect(() => {
414	    try {
415	      const dataUrl = sessionStorage.getItem(PHOTO_STORAGE_KEYS.dataUrl);
416	      const name = sessionStorage.getItem(PHOTO_STORAGE_KEYS.name);
417	      const type = sessionStorage.getItem(PHOTO_STORAGE_KEYS.type);
418	      const wasCapturing = sessionStorage.getItem(PHOTO_STORAGE_KEYS.capturing) === 'true';
419	
420	      if (dataUrl && name) {
421	        const arr = dataUrl.split(',');
422	        const mime = arr[0].match(/:(.*?);/)?.[1] || type || 'image/jpeg';
423	        const bstr = atob(arr[1]);
424	        const u8 = new Uint8Array(bstr.length);
425	        for (let i = 0; i < bstr.length; i++) u8[i] = bstr.charCodeAt(i);
426	        const file = new File([u8], name, { type: mime });
427	        setPhotoFile(file);
428	        setPhotoPreview(dataUrl);
429	        sessionStorage.removeItem(PHOTO_STORAGE_KEYS.capturing);
430	        toast({ title: "Foto restaurada", description: "Sua foto foi recuperada após a captura." });
431	      } else if (wasCapturing) {
432	        sessionStorage.removeItem(PHOTO_STORAGE_KEYS.capturing);
433	      }
434	    } catch (err) {
435	      console.error("Falha ao restaurar foto da perda:", err);
436	      clearPhotoStorage();
437	    }
438	    // eslint-disable-next-line react-hooks/exhaustive-deps
439	  }, []);
440	
441	  useEffect(() => {
442	    fetchLosses();
443	    const fetchAuxData = async () => {
444	      // Products from produtos_master (source of truth)
445	      try {
446	        setLoadingProducts(true);
447	        const { data, error } = await supabase
448	          .from("produtos_master")
449	          .select("id, nome, preco_custo")
450	          .eq("ativo", true)
451	          .order("nome");
452	        if (!error && data) {
453	          setProducts(data.map((p: any) => ({ id: p.id, nome: p.nome, preco_custo: p.preco_custo })));
454	        }
455	      } catch (e) {
456	        console.error(e);
457	      } finally {
458	        setLoadingProducts(false);
459	      }
460	
461	      // Stores
462	      try {
463	        setLoadingStores(true);
464	        const { data, error } = await supabase
465	          .from("lojas")
466	          .select("id, nome, ativo")
467	          .eq("ativo", true)
468	          .order("nome");
469	        if (!error && data) {
470	          setStores(data.map((s: any) => ({ id: s.id, nome: s.nome })));
471	        }
472	      } catch (e) {
473	        console.error(e);
474	      } finally {
475	        setLoadingStores(false);
476	      }
477	
478	      // Users (Usuarios) & Current User ID
479	      try {
480	        const { data, error } = await supabase
481	          .from("usuarios")
482	          .select("id, nome");
483	        if (!error && data) {
484	          setUsers(data as any);
485	        }
486	
487	        const { data: userData } = await supabase.auth.getUser();
488	        if (userData?.user?.id) {
489	          const { data: uData } = await supabase.rpc("get_usuario_id_from_auth", { user_uuid: userData.user.id });
490	          if (uData) setCurrentUserId(uData);
491	        }
492	      } catch (e) {
493	        console.error("Erro ao carregar usuarios", e);
494	      }
495	    };
496	    fetchAuxData();
497	  }, []);
498	
499	  // Selected product's cost price
500	  const selectedProductCost = useMemo(() => {
501	    if (!selectedProductId) return null;
502	    const p = products.find(x => String(x.id) === selectedProductId);
503	    return p?.preco_custo ?? null;
504	  }, [selectedProductId, products]);
505	
506	  const handleSubmit = async () => {
507	    if (!selectedStore) {
508	      toast({ title: "Loja obrigatória", description: "Selecione a loja onde ocorreu a perda.", variant: "destructive" });
509	      return;
510	    }
511	
512	    if (!photoFile) {
513	      toast({ title: "Foto obrigatória", description: "É obrigatório anexar uma foto para registrar a perda.", variant: "destructive" });
514	      return;
515	    }
516	
517	    let prodName = selectedProductQuery;
518	    if (selectedProductId) {
519	      const p = products.find(x => String(x.id) === selectedProductId);
520	      if (p) prodName = p.nome;
521	    }
522	
523	    if (!prodName || !selectedProductId || !quantity || !reason || !lote || !validade) {
524	      toast({ title: "Dados incompletos", description: "Preencha produto, quantidade, motivo, lote e validade.", variant: "destructive" });
525	      return;
526	    }
527	
528	    setIsSubmitting(true);
529	    try {
530	      let finalResponsavelId = currentUserId;
531	      // Fallback if currentUserId wasn't loaded for some reason
532	      if (!finalResponsavelId) {
533	        const { data: userData } = await supabase.auth.getUser();
534	        if (userData?.user?.id) {
535	          const { data: uData } = await supabase.rpc("get_usuario_id_from_auth", { user_uuid: userData.user.id });
536	          finalResponsavelId = uData;
537	        }
538	      }
539	
540	      let fotoUrl = null;
541	      if (photoFile) {
